WITH filtered AS (SELECT id, order_id, method, paid_at, status, DAY(paid_at) AS paid_at_day, COALESCE(method, 'N/A') AS method_filled FROM payments WHERE paid_at >= TO_TIMESTAMP('2023-10-02 08:00:00')), with_gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) > INTERVAL '14' DAY THEN 1 ELSE 0 END AS session_start_flag FROM filtered), sessions_payments AS (SELECT id, order_id, method, paid_at, status, paid_at_day, method_filled, SUM(session_start_flag) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT order_id, DATE_TRUNC('QUARTER', paid_at) AS quarter_start, COUNT(*) AS cnt, COUNT(*) FILTER (WHERE method = 'cash') AS cash_rows, MIN(paid_at) AS first_seen, ROUND(SUM(session_id) / NULLIF(COUNT(CASE WHEN status = 'REFUNDED' THEN 1 END), 0), 2) AS session_id_per_refunded, COUNT(*) FILTER (WHERE method = 'paypal') AS paypal_rows, AVG(paid_at_day) FILTER (WHERE method = 'cash') AS cash_avg_paid_at_day FROM sessions_payments GROUP BY 1, 2 HAVING session_id_per_refunded > 0;
